DROP TABLE IF EXISTS stats;
CREATE TABLE stats (country TEXT, country_ru TEXT, flag TEXT, comp TEXT, comp_name TEXT, comp_ru TEXT, tier INTEGER, agent_status TEXT, bucket TEXT, n INTEGER);
CREATE INDEX idx_stats_country ON stats(country);
CREATE INDEX idx_stats_bucket ON stats(bucket, agent_status);
DROP TABLE IF EXISTS clubs;
CREATE TABLE clubs (club_id TEXT PRIMARY KEY, club TEXT, club_key TEXT, comp TEXT, comp_ru TEXT, comp_name TEXT, country TEXT, country_ru TEXT, flag TEXT, n INTEGER);
CREATE INDEX idx_clubs_key ON clubs(club_key);